package org.sleepwell.app;

/** All calls are serialized by its owner. Counters denote requests, never measured light. */
final class TravelCueSession {
 static final long INTERVAL=15000,PULSE_REQUEST=2,MAX_WAIT=12*3600000L;
 enum Phase {ARMED,OPENING,RUNNING,FINISHED,STOPPED,ERROR,INTERRUPTED}
 interface Clock {long wall();long elapsed();String zone();}
 interface Scheduler {void at(long elapsed,Runnable callback);void cancel();}
 interface Handle {void set(boolean on);void close();}
 interface Request {void close();}
 interface Events {void ready(Handle handle);void lost(String reason);}
 interface Output {Request open(Events events);}
 interface Journal {void save(State state);}
 static final class State {final String nonce,message;final Phase phase;final long start,end;final int requests,skipped;State(String nonce,Phase phase,long start,long end,int requests,int skipped,String message){this.nonce=nonce;this.phase=phase;this.start=start;this.end=end;this.requests=requests;this.skipped=skipped;this.message=message;}boolean busy(){return phase==Phase.ARMED||phase==Phase.OPENING||phase==Phase.RUNNING;}}
 final String nonce;final long start,end;private final long armedWall,armedElapsed,startElapsed,endElapsed;private final String zone;private final Clock clock;private final Scheduler scheduler;private final Output output;private final Journal journal;private final java.util.function.BooleanSupplier alive;
 private Phase phase=Phase.ARMED;private int requests,skipped,index;private long generation;private Handle handle;private Request opening;private String message="";
 TravelCueSession(String nonce,TravelCuePlan.Window window,Clock clock,Scheduler scheduler,Output output,Journal journal,java.util.function.BooleanSupplier alive){if(!java.util.UUID.fromString(nonce).toString().equals(nonce))throw new IllegalArgumentException("Invalid cue identity");this.nonce=nonce;this.start=window.start;this.end=window.end;this.clock=clock;this.scheduler=scheduler;this.output=output;this.journal=journal;this.alive=alive;armedWall=clock.wall();armedElapsed=clock.elapsed();zone=clock.zone();if(!alive.getAsBoolean()||end<=armedWall||start-armedWall>MAX_WAIT)throw new IllegalArgumentException("Use an active manual recording and a window within twelve hours.");startElapsed=Math.addExact(armedElapsed,start-armedWall);endElapsed=Math.addExact(armedElapsed,end-armedWall);}
 State state(){return new State(nonce,phase,start,end,requests,skipped,message);}
 void start(){if(generation!=0)throw new IllegalStateException("This cue session was already armed.");generation=1;save();tick();}
 private boolean valid(){if(!state().busy())return false;if(!alive.getAsBoolean()){stop("The manual tracking session ended.");return false;}if(!zone.equals(clock.zone())||clockChanged()){stop("Clock or time zone changed. Review cues before arming again.");return false;}return true;}
 private boolean clockChanged(){try{long drift=Math.subtractExact(Math.subtractExact(clock.wall(),armedWall),Math.subtractExact(clock.elapsed(),armedElapsed));return drift>2000||drift< -2000;}catch(ArithmeticException invalid){return true;}}
 private void later(long at,Runnable callback){long own=generation;scheduler.at(at,()->{if(own==generation)callback.run();});}
 private void tick(){if(!valid())return;long now=clock.elapsed();if(now>=endElapsed){finish(Phase.FINISHED,"Cue window finished. Flashlight release requested.");return;}if(now<startElapsed){later(Math.min(startElapsed,now+1000),this::tick);return;}phase=Phase.OPENING;save();long own=generation;later(Math.min(endElapsed,clock.elapsed()+3500),()->{if(phase==Phase.OPENING)finish(Phase.ERROR,"The flashlight did not become ready.");});Request request=output.open(new Events(){public void ready(Handle value){if(own!=generation||!valid()){value.close();return;}handle=value;phase=Phase.RUNNING;index=(int)Math.max(0,(clock.elapsed()-startElapsed+INTERVAL-1)/INTERVAL);skipped=index;save();pulse();}public void lost(String reason){if(own==generation&&state().busy())finish(Phase.ERROR,reason);else if(reason.equals("The flashlight could not be released.")){phase=Phase.ERROR;message=reason;save();}}});opening=request;if(!state().busy())request.close();}
 private void pulse(){if(!valid())return;long now=clock.elapsed();if(now>=endElapsed){finish(Phase.FINISHED,"Cue window finished. Flashlight release requested.");return;}long due=startElapsed+index*INTERVAL;if(now<due){later(Math.min(due,endElapsed),this::pulse);return;}if(now>due+1000){int next=(int)((now-startElapsed+INTERVAL-1)/INTERVAL);skipped+=Math.max(1,next-index);index=Math.max(index+1,next);save();later(Math.min(startElapsed+index*INTERVAL,endElapsed),this::pulse);return;}requests++;save();try{handle.set(true);}catch(RuntimeException failure){finish(Phase.ERROR,"The flashlight request failed.");return;}later(Math.min(now+PULSE_REQUEST,endElapsed),()->{try{if(handle!=null)handle.set(false);}catch(RuntimeException failure){finish(Phase.ERROR,"The flashlight could not be released.");return;}index++;if(valid())later(Math.min(startElapsed+index*INTERVAL,endElapsed),this::pulse);});}
 void stop(String why){if(!state().busy())return;finish(Phase.STOPPED,why);}
 private void finish(Phase next,String why){if(!state().busy())return;phase=next;message=why;generation++;scheduler.cancel();Handle owned=handle;handle=null;Request pending=opening;opening=null;boolean failed=false;try{if(owned!=null)owned.close();}catch(RuntimeException failure){failed=true;}try{if(pending!=null)pending.close();}catch(RuntimeException failure){failed=true;}if(failed){phase=Phase.ERROR;message="The flashlight could not be released.";}save();}
 private void save(){try{journal.save(state());}catch(RuntimeException failure){phase=Phase.ERROR;message="Cue status could not be saved. Light output was stopped.";generation++;scheduler.cancel();Handle owned=handle;handle=null;if(owned!=null)try{owned.close();}catch(RuntimeException ignored){}Request pending=opening;opening=null;if(pending!=null)try{pending.close();}catch(RuntimeException ignored){}throw failure;}}
}
